Here is a basic TypeScript React app that displays GitLab CI/CD statistics:

```tsx
import React, { useState, useEffect } from 'react';

interface GitLabData {
  jobs: {
    total: number;
    success: number;
    failed: number;
    canceled: number;
  };
  runners: {
    total: number;
    active: number;
    paused: number;
  }
}

const GitLabStats = () => {
  const [data, setData] = useState<GitLabData | null>(null);

  useEffect(() => {
    fetch('/gitlab/api/v4/jobs/statistics')
      .then(res => res.json())
      .then(setData);

    fetch('/gitlab/api/v4/runners')
      .then(res => res.json())
      .then(runnersData => {
        setData(prevData => ({
          ...prevData!,
          runners: runnersData
        }));
      });
  }, []);

  if (!data) {
    return <div>Loading...</div>
  }

  return (
    <div>
      <h1>GitLab CI/CD Statistics</h1>

      <h2>Jobs</h2>
      <p>Total: {data.jobs.total}</p>
      <p>Success: {data.jobs.success}</p>
      <p>Failed: {data.jobs.failed}</p>
      <p>Canceled: {data.jobs.canceled}</p>

      <h2>Runners</h2>
      <p>Total: {data.runners.total}</p>
      <p>Active: {data.runners.active}</p>
      <p>Paused: {data.runners.paused}</p>
    </div>
  );
}

export default GitLabStats;
```

This component:

- Fetches GitLab CI/CD jobs statistics and runners data on mount
- Stores the data in state 
- Renders the statistics with the fetched data
- Shows loading state while data is being fetched

