Here is an updated TypeScript React app that displays GitLab CI/CD statistics across multiple groups and projects:

```tsx
import React, { useState, useEffect } from 'react';

interface GitLabData {
  jobs: {
    total: number;
    success: number;
    failed: number;
    canceled: number;
  };
  runners: {
    total: number;
    active: number;
    paused: number;
  }
}

interface GitLabGroup {
  name: string;
  projects: GitLabProject[];
}

interface GitLabProject {
  name: string;
  jobs: GitLabData;  
}

const GitLabStats = () => {
  const [groups, setGroups] = useState<GitLabGroup[] | null>(null);

  useEffect(() => {
    fetch('/gitlab/api/v4/groups')
      .then(res => res.json())
      .then(setGroups);
  }, []);

  if (!groups) {
    return <div>Loading...</div>
  }

  return (
    <div>
      {groups.map(group => (
        <div key={group.name}>
          <h1>{group.name}</h1>
          {group.projects.map(project => (
            <div key={project.name}>
              <h2>{project.name}</h2>

              <h3>Jobs</h3>
              <p>Total: {project.jobs.total}</p>
              <p>Success: {project.jobs.success}</p>
              <p>Failed: {project.jobs.failed}</p>
              <p>Canceled: {project.jobs.canceled}</p>

              <h3>Runners</h3>
              <p>Total: {project.jobs.runners.total}</p>
              <p>Active: {project.jobs.runners.active}</p>
              <p>Paused: {project.jobs.runners.paused}</p>
            </div>
          ))}
        </div>
      ))}
    </div>
  );
}

export default GitLabStats;
```

This component now:

- Fetches GitLab groups 
- For each group, renders the group name and projects
- For each project, renders the project name and CI/CD statistics

